/**
 * Print docs/use-cases.html to the PDF that ships beside it.
 *
 * Same one-artifact-two-copies discipline as scripts/guide-pdf.mjs, for the
 * same reason: `docs/Relay-Use-Cases.pdf` was generated by hand on 2026-08-13
 * and every later change to the HTML silently left the PDF describing an older
 * product. The PDF is derived, never remembered.
 *
 * Unlike the guide, this document's images are RELATIVE (`../public/guide/...`),
 * so it prints correctly over file:// with no server. That is deliberate — the
 * use-case document is evidence, and evidence should be printable from a bare
 * checkout.
 *
 *   node scripts/use-cases-pdf.mjs
 */
import { writeFileSync, statSync } from 'node:fs';
import { resolve } from 'node:path';

const HOME = (process.env.HOME || process.env.USERPROFILE || '').split('\\').join('/');
const PLAYWRIGHT =
  process.env.PLAYWRIGHT_MODULE ||
  `file:///${HOME}/CascadeProjects/__shared-tools/node_modules/playwright/index.mjs`;
const { chromium } = await import(PLAYWRIGHT);

const SRC = resolve('docs/use-cases.html');
const OUT = 'docs/Relay-Use-Cases.pdf';

const browser = await chromium.launch();
const page = await browser.newPage();

/** Images that fail to load must fail the run, not quietly print as gaps. */
const missing = [];
page.on('requestfailed', (r) => {
  if (/\.(png|jpe?g|svg|webp)$/i.test(r.url())) missing.push(r.url());
});

await page.goto(`file:///${SRC.split('\\').join('/')}`, { waitUntil: 'networkidle' });

// Every <img> decoded before printing — networkidle says requests finished,
// not that bitmaps are ready to paint. Same beat guide-pdf.mjs waits out.
const decoded = await page.evaluate(async () => {
  const imgs = [...document.images];
  await Promise.all(imgs.map((i) => (i.complete ? null : i.decode().catch(() => null))));
  return { total: imgs.length, broken: imgs.filter((i) => !i.naturalWidth).length };
});

if (missing.length || decoded.broken > 0) {
  console.error(
    `FAILED — ${missing.length} asset requests failed, ${decoded.broken} of ${decoded.total} images did not render.`,
  );
  if (missing.length) console.error('  ' + missing.join('\n  '));
  await browser.close();
  process.exit(1);
}

const pdf = await page.pdf({ format: 'A4', printBackground: true });
writeFileSync(OUT, pdf);
await browser.close();

console.log(`${OUT} — ${decoded.total} images, ${(statSync(OUT).size / 1024 / 1024).toFixed(1)} MB`);
